package cn.zhuatech.auditagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ControlCoverageService{public Result evaluate(Request r){double coverage=r.sampledItems()*100.0/r.populationSize();int score=(int)Math.round(Math.min(100,coverage*2)+Math.min(25,r.highRiskItemsSampled()*5)+(r.evidenceComplete()?20:0)+(r.independentReview()?15:0)-Math.min(30,r.exceptionsFound()*5));score=Math.max(0,Math.min(100,score));List<String> actions=new ArrayList<>();if(coverage<10)actions.add("扩大总体抽样覆盖");if(r.highRiskItemsSampled()==0)actions.add("纳入高风险项目定向抽样");if(!r.evidenceComplete())actions.add("补齐样本测试证据");if(!r.independentReview())actions.add("安排独立复核");String status=score<55?"INCREASE_SAMPLE":score<80?"REVIEW":"ADEQUATE";if(actions.isEmpty())actions.add("控制测试覆盖和证据满足审计要求");return new Result(Math.round(coverage*10)/10.0,score,status,actions);}
 public record Request(@Min(1) int populationSize,@Min(1) int sampledItems,@Min(0) int highRiskItemsSampled,@Min(0) int exceptionsFound,@NotNull Boolean evidenceComplete,@NotNull Boolean independentReview){}public record Result(double sampleCoverage,int coverageScore,String status,List<String> actions){} }
